using UnityEngine;

public class ColonyAcidGun : MonoBehaviour { public Transform muzzle; public float damage = 18f; public float speed = 22f; public float interval = .18f; public bool playerOwned; public ColonyHealth.Team team = ColonyHealth.Team.Player; public Color globColor = Color.green; public AudioClip spitSound; float cooldown; static ColonyAcidGlob prefab; public Vector3 Origin => muzzle != null ? muzzle.position : transform.position + Vector3.up * .45f; public static void BindPrefab(ColonyAcidGlob value) => prefab = value; public void ResetWeapon() => cooldown = 0f; void Update() { cooldown = Mathf.Max(0f, cooldown - Time.deltaTime); if (!playerOwned) return; if (Input.GetKey(KeyCode.LeftAlt) || Input.GetKey(KeyCode.RightAlt)) return; var motor = GetComponent<PlayerController>(); if (motor == null || !motor.InputEnabled || !Input.GetButton("Fire1")) return; var cam = motor.LookTransform; Vector3 target = cam.position + cam.forward * 30f; if (Physics.Raycast(cam.position, cam.forward, out var hit, 30f, ~0, QueryTriggerInteraction.Ignore)) target = hit.point; TryFire(target - Origin); } public bool TryFire(Vector3 direction) { if (cooldown > 0f || prefab == null || direction.sqrMagnitude < .001f || !ColonyGameDirector.Instance.IsPlaying) return false; var glob = Instantiate(prefab); glob.Launch(Origin, direction, speed, damage, gameObject, team); cooldown = interval; if (spitSound != null) AudioSource.PlayClipAtPoint(spitSound, Origin, playerOwned ? .22f : .06f); EventDispatcher.SendEvent(GameEventTypes.WeaponEventType.Fired, gameObject.GetInstanceID(), 0, damage); return true; } }